  async start(): Promise<void> {
    if (this.child) throw new Error("Pi RPC client is already started.");
    const configuredExecutable = this.options.executable ?? resolveDefaultPiExecutable();
    const piArgs = ["--mode", "rpc", ...(this.options.args ?? [])];
    const command = resolvePiCommand(configuredExecutable, piArgs);
    const executable = command.executable;
    const args = command.args;
    this.options.logger?.info("pi.spawn", { executable, args: summarizePiArgs(args), cwd: this.options.cwd });
    const child = spawn(executable, args, {
      cwd: this.options.cwd,
      env: { ...process.env, ...this.options.env },
      stdio: ["pipe", "pipe", "pipe"],
    });
    this.child = child;
    this.options.logger?.info("pi.spawned", { pid: child.pid });

    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk: string) => this.consumeStdout(chunk));
    child.stderr.on("data", (chunk: string) => {
      this.stderrBuffer = (this.stderrBuffer + chunk).slice(-64_000);
      this.options.logger?.warn("pi.stderr", { chunk });
      this.emit("stderr", chunk);
    });
    child.on("error", (error) => {
      this.options.logger?.error("pi.process_error", error);
      this.failAll(new Error(`Failed to start Pi: ${error.message}`));
    });
    child.on("exit", (code, signal) => {
      const suffix = this.stderrBuffer.trim() ? `\n${this.stderrBuffer.trim()}` : "";
      const error = new Error(`Pi RPC exited (code=${code ?? "null"}, signal=${signal ?? "none"}).${suffix}`);
      this.options.logger?.error("pi.exit", { code, signal, stopping: this.stopping, stderrTail: this.stderrBuffer.slice(-8_000) });
      this.child = undefined;
      if (!this.stopping) this.emit("exit", error);
      this.failAll(error);
    });

    await new Promise<void>((resolve, reject) => {
      const timer = setTimeout(resolve, 150);
      child.once("error", (error) => {
        clearTimeout(timer);
        reject(error);
      });
      child.once("exit", (code, signal) => {
        clearTimeout(timer);
        reject(new Error(`Pi exited during startup (code=${code}, signal=${signal ?? "none"}).`));
      });
    });
  }

